 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A diagonal pair of identical markers gives the ray direction; continue
    # from the lower member, stopping at any non-background object.
    pairs = []
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == grid[0][0]:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == color:
                    pairs.append((r, c, r + 1, nc, color))
    if not pairs:
        return out
    # Prefer the color forming the largest connected group, then a diagonal pair.
    r1, c1, r2, c2, color = pairs[0]
    dr, dc = r2 - r1, c2 - c1
    r, c = r2, c2
    while 0 <= r + dr < h and 0 <= c + dc < w:
        nr, nc = r + dr, c + dc
        if grid[nr][nc] != grid[0][0]:
            break
        out[nr][nc] = color
        r, c = nr, nc
    return out
