 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    # Each object's diagonal pattern establishes direction and color; extend
    # from the extremal end of its visible diagonal line.
    coords = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg:
                coords.setdefault(v, []).append((r, c))
    for color, pts in coords.items():
        pairs = []
        for r, c in pts:
            for dr, dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                if (r+dr,c+dc) in pts:
                    pairs.append((r,c,dr,dc))
        if not pairs:
            continue
        r,c,dr,dc = pairs[0]
        # Extend in that diagonal direction until edge or obstacle.
        while 0 <= r+dr < h and 0 <= c+dc < w:
            r += dr; c += dc
            if grid[r][c] != bg:
                break
            out[r][c] = color
    return out
